<?php

// config/local.php is not committed: it holds secrets (DB credentials,
// cookie key). In production it is generated by the deploy workflow.
$localFile = __DIR__ . '/local.php';
$local = is_file($localFile) ? require $localFile : [];

$config = [
    'id' => 'avoxe',
    'basePath' => dirname(__DIR__),
    'bootstrap' => ['log'],
    'defaultRoute' => 'site/index',
    'components' => [
        'request' => [
            // Requests reach web/ through a rewrite from the site root,
            // so the public base URL is always the domain root.
            'baseUrl' => '',
            'cookieValidationKey' => $local['cookieValidationKey'] ?? 'dev-only-insecure-key',
            'parsers' => [
                'application/json' => yii\web\JsonParser::class,
            ],
        ],
        'cache' => [
            'class' => yii\caching\FileCache::class,
        ],
        'log' => [
            'targets' => [
                [
                    'class' => yii\log\FileTarget::class,
                    'levels' => ['error', 'warning'],
                ],
            ],
        ],
        'urlManager' => [
            'enablePrettyUrl' => true,
            'showScriptName' => false,
            'rules' => [
                'api/<action:[\w-]+>' => 'api/<action>',
                // Everything else is a client-side route of the Vue app.
                '<path:.*>' => 'site/index',
            ],
        ],
    ],
];

if (!empty($local['db'])) {
    $config['components']['db'] = array_merge([
        'class' => yii\db\Connection::class,
        'charset' => 'utf8mb4',
    ], $local['db']);
}

return $config;
